package com.bank.product.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.nio.charset.StandardCharsets; import java.util.*;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter {
 private final JwtParser parser; public JwtAuthenticationFilter(@Value("${security.jwt.secret}") String secret){if(secret.length()<32)throw new IllegalArgumentException("JWT_SECRET must contain at least 32 characters");parser=Jwts.parser().verifyWith(Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8))).build();}
 @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{Claims c=parser.parseSignedClaims(h.substring(7)).getPayload();String username=c.getSubject();Object raw=c.get("roles");if(raw==null)raw=c.get("role");List<SimpleGrantedAuthority> auth=new ArrayList<>();if(raw instanceof Collection<?> values)values.forEach(x->auth.add(authority(x.toString())));else if(raw!=null)auth.add(authority(raw.toString()));SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(username,null,auth));}catch(JwtException ignored){SecurityContextHolder.clearContext();}chain.doFilter(req,res);}
 private SimpleGrantedAuthority authority(String value){String v=value.toUpperCase(Locale.ROOT);return new SimpleGrantedAuthority(v.startsWith("ROLE_")?v:"ROLE_"+v);}
}
